-- Seed data: a goofy starter menu. Such data. Very test.
-- Safe to re-run: ON CONFLICT DO NOTHING skips rows that already exist.

-- sort_order has gaps of 10 so a new category can slot in between without renumbering.
insert into public.categories (slug, name, sort_order) values
  ('much-rolls',  'Much Rolls',  10),
  ('very-nigiri', 'Very Nigiri', 20),
  ('such-sides',  'Such Sides',  30),
  ('wow-drinks',  'Wow Drinks',  40)
on conflict (slug) do nothing;

-- Ids are generated by the database, so items find their category by slug instead of a hardcoded id.
-- VALUES builds an inline table (v), which we JOIN to categories to swap each slug for its id.
insert into public.menu_items
  (category_id, name, description, price_cents, spice_level, wow_level, is_available)
select
  c.id, v.name, v.description, v.price_cents, v.spice_level,
  v.wow_level::public.wow_level,  -- text → enum needs an explicit cast
  v.is_available
from (values
  -- Much Rolls
  ('much-rolls', 'Much Wow Roll',          'Salmon, avocado, cream cheese, torched spicy mayo. The flagship. Wow.',   1490, 2, 'much wow',    true),
  ('much-rolls', 'Kabosu Dragon Roll',     'Eel and cucumber inside, avocado scales outside. Very majestic.',        1690, 0, 'much wow',    true),
  ('much-rolls', 'Such Spicy Tuna Roll',   'Tuna, sriracha, scallion. Such heat. Much brave.',                       1290, 4, 'such delish', true),
  ('much-rolls', 'Bonk Roll',              'Shrimp tempura so crunchy it bonks back.',                               1390, 1, 'such delish', true),
  ('much-rolls', 'Cheems Veggie Roll',     'Cucumbr, avocabo, carrot. Cheems approves.',                             1090, 0, 'very ok',     true),
  ('much-rolls', 'California Shibe Roll',  'Crab, avocado, cucumber. A classic, now with more shibe.',               1190, 0, 'very ok',     true),
  ('much-rolls', 'Ghost Pepper Doge Roll', 'Very regret. Much fire. Sold out because too many brave doges.',          1590, 5, 'very ok',     false),

  -- Very Nigiri (2 pieces)
  ('very-nigiri', 'Such Salmon Nigiri',    'Buttery salmon on rice. Such simple. Much good.',                         690, 0, 'much wow',    true),
  ('very-nigiri', 'Hamachi Heckin Nigiri', 'Yellowtail with a slice of jalapeño. Heckin fancy.',                       850, 2, 'much wow',    true),
  ('very-nigiri', 'Very Tuna Nigiri',      'Lean maguro. Very red. Very fresh.',                                      790, 0, 'such delish', true),
  ('very-nigiri', 'Much Unagi Nigiri',     'Grilled eel with sweet glaze. Sticky paws guaranteed.',                   890, 0, 'such delish', true),
  ('very-nigiri', 'Ebi Nigiri',            'Shrimp. Simple. Honest. Very ok.',                                        590, 0, 'very ok',     true),
  ('very-nigiri', 'Tamago Nigiri',         'Sweet egg omelette. For doges who fear fish.',                            490, 0, 'very ok',     true),

  -- Such Sides
  ('such-sides', 'Gyoza of Wonder',        'Six pan-fried pork dumplings. Crispy bottoms. Wow.',                      690, 0, 'much wow',    true),
  ('such-sides', 'Karaage Bork Bites',     'Japanese fried chicken with lemon. Bork bork.',                           790, 1, 'much wow',    true),
  ('such-sides', 'Very Miso Soup',         'Tofu, wakame, scallion. Warm like a doge hug.',                           390, 0, 'such delish', true),
  ('such-sides', 'Spicy Edamame',          'Tossed in garlic chili oil. Such pop. Much tingle.',                      490, 3, 'such delish', true),
  ('such-sides', 'Much Edamame',           'Steamed, sea salt. Pop pop pop.',                                         450, 0, 'very ok',     true),
  ('such-sides', 'Seaweed Salad',          'Sesame, chili flakes, ocean vibes.',                                      450, 1, 'very ok',     true),
  ('such-sides', 'Extra Wasabi',           'Such green. Much nose pain.',                                             100, 5, 'very ok',     true),

  -- Wow Drinks
  ('wow-drinks', 'Very Matcha Latte',      'Ceremonial matcha, oat milk. Very green. Much calm.',                     450, 0, 'much wow',    true),
  ('wow-drinks', 'Yuzu Doge-ade',          'Yuzu lemonade. Sour face guaranteed.',                                    400, 0, 'much wow',    true),
  ('wow-drinks', 'Such Ramune',            'Marble soda. The marble stays in. Do not ask.',                           350, 0, 'such delish', true),
  ('wow-drinks', 'Calpico Cloud',          'Milky, fizzy, fluffy, like doge fur.',                                    350, 0, 'such delish', true),
  ('wow-drinks', 'Much Green Tea',         'Hot sencha. Free refills for good doges.',                                250, 0, 'very ok',     true),
  ('wow-drinks', 'Doge Juice',             'Mystery flavour. Nobody knows. Not even doge. Temporarily unavailable.',  300, 0, 'very ok',     false)
) as v (category_slug, name, description, price_cents, spice_level, wow_level, is_available)
join public.categories c on c.slug = v.category_slug
on conflict (category_id, name) do nothing;

-- The shop: Sakura, Chiba, Kabosu's hometown. The street is made up; the city and time zone are real.
insert into public.store_info (name, address, timezone, latitude, longitude) values
  ('kabosushi', '1-1 Much Wow Street, Sakura, Chiba, Japan', 'Asia/Tokyo', 35.723700, 140.223900)
on conflict (id) do nothing;

